#!/usr/bin/env bash
# hardware-profile.sh — apply a [hardware.<id>] profile from tunaos.toml to a
# parent image, and record what the image carries.
#
# Usage: hardware-profile.sh <profile id>
#
# The profile is data: build_scripts/lib/hardware-profiles.json, generated by
# `scripts/config.py generate-hardware-profiles`. In order this script:
#   1. refuses an architecture or package manager the profile does not list;
#   2. enables the profile's repositories and swaps the kernel (kernel != stock);
#   3. installs the profile's packages, copies system_files_overrides/
#      hardware-<id>/ and refuses its conflicting packages;
#   4. writes /usr/lib/bootc/kargs.d/10-<id>.toml;
#   5. writes /usr/lib/dracut/dracut.conf.d/90-<id>.conf;
#   6. places the device tree for the image's boot layout;
#   7. rebuilds the initramfs the way the parent built it;
#   8. writes /usr/share/tunaos/hardware-<id>.txt and fails on any MISSING line.
#
# Test hooks, empty in a build: TUNAOS_SYSROOT prefixes every image path (the
# same hook as bootc/dracut-config.sh); TUNAOS_HARDWARE_PROFILES and
# TUNAOS_CONTEXT point at a fixture profile file and build context.
set -euo pipefail

PROFILE_ID="${1:-${HARDWARE_PROFILE:-}}"
if [[ -z "${PROFILE_ID}" ]]; then
	echo "ERROR: usage: hardware-profile.sh <profile id>" >&2
	exit 2
fi

SCRIPT_DIR="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")"
CONTEXT="${TUNAOS_CONTEXT:-$(dirname "$(dirname "${SCRIPT_DIR}")")}"
PROFILES="${TUNAOS_HARDWARE_PROFILES:-${SCRIPT_DIR}/../lib/hardware-profiles.json}"
R="${TUNAOS_SYSROOT:-}"
# shellcheck source=build_scripts/overlay/lib/hardware_inventory.sh
. "${SCRIPT_DIR}/lib/hardware_inventory.sh"

if ! command -v jq >/dev/null 2>&1; then
	echo "ERROR: hardware-profile.sh needs jq to read ${PROFILES}" >&2
	exit 1
fi
if ! profile="$(jq -ce --arg id "${PROFILE_ID}" '.profiles[$id]' "${PROFILES}")"; then
	echo "ERROR: no hardware profile '${PROFILE_ID}' in ${PROFILES}" >&2
	exit 1
fi
# Print one value per line for a jq path into the profile.
values() { jq -r "$1 | if type == \"array\" then .[] else . end // empty" <<<"${profile}"; }
listed() { jq -e --arg value "$2" "$1 | index(\$value) != null" <<<"${profile}" >/dev/null; }

printf '::group:: === hardware profile %s ===\n' "${PROFILE_ID}"

# ── 1. guards ────────────────────────────────────────────────────────────────
arch="$(uname -m)"
if ! listed .architectures "${arch}"; then
	echo "ERROR: hardware profile ${PROFILE_ID} applies to $(values .architectures | paste -sd, -) builds, not ${arch}" >&2
	exit 1
fi
manager=""
for candidate in dnf pacman zypper apt-get emerge; do
	if command -v "${candidate}" >/dev/null 2>&1; then
		manager="${candidate}"
		break
	fi
done
case "${manager}" in
apt-get) manager=apt ;;
emerge) manager=portage ;;
esac
if [[ -z "${manager}" ]] || ! listed .package_managers "${manager}"; then
	echo "ERROR: hardware profile ${PROFILE_ID} supports $(values .package_managers | paste -sd, -) parents, not ${manager:-an image without a known package manager}" >&2
	exit 1
fi
echo "hardware-profile.sh: ${PROFILE_ID} on ${arch} with ${manager}"

pkg_install() {
	case "${manager}" in
	dnf) dnf -y install "$@" ;;
	pacman) pacman -S --noconfirm --needed "$@" ;;
	zypper) zypper --non-interactive install --no-recommends "$@" ;;
	apt) apt-get update -qq && apt-get install -y --no-install-recommends "$@" ;;
	portage) emerge --verbose --getbinpkg "$@" ;;
	esac
}
pkg_installed() {
	case "${manager}" in
	dnf | zypper) rpm -q "$1" >/dev/null 2>&1 ;;
	pacman) pacman -Q "$1" >/dev/null 2>&1 ;;
	apt) dpkg-query -W -f='${Status}' "$1" 2>/dev/null | grep -q 'install ok installed' ;;
	portage) compgen -G "${R}/var/db/pkg/$1-[0-9]*" >/dev/null ;;
	esac
}
pkg_clean() {
	case "${manager}" in
	dnf) dnf clean all ;;
	pacman) pacman -Scc --noconfirm >/dev/null ;;
	zypper) zypper clean --all ;;
	apt) apt-get clean ;;
	portage) : ;;
	esac
}
# copr:<owner>/<project> or an https:// .repo URL; validated in tunaos.toml.
enable_repo() {
	case "$1" in
	copr:*) dnf -y copr enable "${1#copr:}" ;;
	*) dnf config-manager addrepo --overwrite --from-repofile="$1" ;;
	esac
}
newest_kernel() {
	find "${R}/usr/lib/modules" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' | sort -V | tail -n1
}

# ── 2. repositories and kernel ───────────────────────────────────────────────
while IFS= read -r repo; do
	enable_repo "${repo}"
done < <(values ".repos.${manager}")

kernel_swapped=0
if [[ "$(jq -r '.kernel | type' <<<"${profile}")" == object ]]; then
	kernel_pkg="$(values ".kernel.${manager}")"
	kernel_repo="$(values .kernel.repo)"
	if [[ -z "${kernel_pkg}" || "${manager}" != dnf ]]; then
		echo "ERROR: hardware profile ${PROFILE_ID} names no ${manager} kernel package; only dnf kernel swaps are implemented" >&2
		exit 1
	fi
	enable_repo "${kernel_repo}"
	owner_project="${kernel_repo#copr:}"
	kernel_repo_id="copr:copr.fedorainfracloud.org:${owner_project%%/*}:${owner_project#*/}"

	# The profile's kernel is required for its hardware, and a stock kernel
	# must never silently win.
	#
	# The obstacle, finally named by dnf itself in run 34762701445 (T2):
	#
	#   Argument 'kernel-7.1.9-200.t2.fc44' matches only packages excluded
	#   by versionlock.
	#
	# 10-base-packages.sh runs `dnf versionlock add kernel kernel-core …` against
	# the INSTALLED Fedora kernel, which pins it and excludes every other
	# version — the profile's build included. That one fact explains three
	# earlier failures that each looked like something else:
	#
	#   `--from-repo=<copr> kernel` → "No match for argument 'kernel' in
	#     repositories 'copr:…'". The only candidates in that repo were t2
	#     versions, all locked out, so dnf reported the emptiness in the
	#     vocabulary of the pin. Nothing was wrong with the pin, the repo or
	#     the packages (#2494 blamed the flag's scope, and was wrong).
	#   `repoquery --repo=<copr> 'kernel*'` → lists all 18. repoquery does not
	#     apply versionlock's excludes, which is why the same id and options
	#     succeeded and failed feet apart in one job (#2497 read that as
	#     `--from-repo` being broken, and was wrong).
	#   `grep -E '^(exclude|excludepkgs)=' /etc/dnf/dnf.conf /etc/yum.repos.d/`
	#     → "(none)". True, and beside the point: versionlock keeps its own
	#     list, which that probe never looked at (#2495 blamed the base image's
	#     exclude filters, and was wrong).
	#
	# The two other kernel swaps in this repo both evade the lock without
	# meeting it. nvidia's bypasses dnf entirely (`rpm -ivh`, overrides/nvidia/
	# 10-kernel-swap.sh) and asahi's installs `kernel-16k`, a name the lock list
	# does not carry. A profile kernel named exactly `kernel` is the first swap
	# the lock actually bites.
	#
	# So unlock, swap, and re-lock on what we installed. Re-locking is the same
	# thing 10-kernel-swap.sh does after its swap, for the same reason: "a later
	# transaction pulling a different kernel would silently undo the whole point
	# of this script." The EVR comes from the repository rather than a literal,
	# so a repository rebuild needs no edit here, and the EVR assertion below is
	# the guarantee.
	echo "== kernel packages before the swap =="
	rpm -qa 'kernel*' | sort
	echo "== exclude filters in force =="
	grep -rHnE '^[[:space:]]*(exclude|excludepkgs)[[:space:]]*=' \
		/etc/dnf/dnf.conf /etc/yum.repos.d/ || echo "(none)"
	# The probe that would have found this on day one. dnf.conf and the .repo
	# files are not the only place a package can be filtered out.
	echo "== versionlock entries in force =="
	dnf versionlock list 2>&1 || echo "(versionlock unavailable)"

	echo "== what the pinned repo offers =="
	dnf -y repoquery --repo="${kernel_repo_id}" --qf '%{name}-%{evr}\n' "${kernel_pkg}*" || true

	kernel_evr="$(dnf -y repoquery --repo="${kernel_repo_id}" --qf '%{evr}\n' "${kernel_pkg}" | sort -V | tail -n1)"
	if [[ -z "${kernel_evr}" ]]; then
		echo "ERROR: ${kernel_repo} offers no ${kernel_pkg} build" >&2
		exit 1
	fi
	echo "hardware-profile.sh: installing ${kernel_pkg} ${kernel_evr} from ${kernel_repo_id}"

	# Release the stock kernel's lock, or the install below matches nothing.
	# Every name 10-base-packages.sh locks, so no straggler keeps a hold.
	dnf versionlock delete kernel kernel-devel kernel-devel-matched kernel-core \
		kernel-modules kernel-modules-core kernel-modules-extra kernel-uki-virt ||
		echo "hardware-profile.sh: no versionlock entries to delete"

	kernel_set=("${kernel_pkg}" "${kernel_pkg}-core" "${kernel_pkg}-modules" "${kernel_pkg}-modules-core")
	dnf -y remove --noautoremove "${kernel_set[@]}" || true
	# kernel-core's %posttrans runs rpm-ostree kernel-install, which invokes
	# dracut, and /boot is a tmpfs mount in Containerfile.overlay. dracut stages
	# its output in the default tmpdir and renames it into /boot, and that rename
	# crosses a filesystem boundary:
	#
	#   >>> Generating initramfs
	#   >>> error: rpm-ostree kernel-install: Adding kernel: Running dracut:
	#       Invalid cross-device link (os error 18)
	#
	# run 34765692106. dnf reported success anyway, so the image shipped a t2
	# kernel with no initramfs and panicked on first boot:
	#
	#   Kernel panic - not syncing: VFS: Unable to mount root fs on unknown-block(0,0)
	#   ... Not tainted 7.1.9-200.t2.fc44.x86_64
	#
	# TMPDIR=/boot is the fix overrides/nvidia/10-kernel-swap.sh uses for the
	# identical EXDEV, and it does NOT work here. It is kept only because that
	# script sets it on `rpm -ivh` directly, where rpm inherits it; dnf adds a
	# layer, and rpm runs scriptlets with a sanitised environment, so the setting
	# never reaches %posttrans. Measured: run 34768771243 carries this exact line
	# and still logs the EXDEV at the same point. Do not read this as load-bearing
	# and do not delete it as dead — it is neither, and the next person deserves
	# to know which.
	#
	# What actually produces a bootable image is the explicit rebuild below. Same
	# run: a 278 MB initramfs in /lib/modules, a green boot gate, and Promote.
	TMPDIR=/boot dnf -y install --allowerasing "${kernel_set[@]/%/-${kernel_evr}}"

	# Belt and braces, and the shape 20-nvidia.sh uses: build the initramfs
	# explicitly into /lib/modules, which is part of the image, rather than
	# trusting a %posttrans whose failure does not fail the transaction.
	swapped_kver="$(rpm -q "${kernel_pkg}-core" --qf '%{VERSION}-%{RELEASE}.%{ARCH}\n' | tail -n1)"
	echo "hardware-profile.sh: building the initramfs for ${swapped_kver}"
	/usr/bin/dracut --no-hostonly --kver "${swapped_kver}" --reproducible --tmpdir /boot \
		--zstd -v --add ostree -f "/lib/modules/${swapped_kver}/initramfs.img"

	# Assert it, because the failure that caused the panic was silent. An
	# initramfs that is missing or implausibly small cannot mount the root.
	swapped_initramfs="/lib/modules/${swapped_kver}/initramfs.img"
	if [[ ! -s "${swapped_initramfs}" ]]; then
		echo "ERROR: no initramfs at ${swapped_initramfs} after the swap" >&2
		exit 1
	fi
	swapped_initramfs_size="$(stat -c %s "${swapped_initramfs}")"
	if ((swapped_initramfs_size < 10000000)); then
		echo "ERROR: initramfs ${swapped_initramfs} is only ${swapped_initramfs_size} bytes" >&2
		echo "       a usable one carries the root storage drivers and is far larger" >&2
		exit 1
	fi
	echo "hardware-profile.sh: initramfs ${swapped_initramfs} is ${swapped_initramfs_size} bytes"

	# Re-lock, now on the profile's kernel. Leaving the image unlocked would
	# let any later transaction pull a stock kernel back over this one.
	dnf versionlock add "${kernel_set[@]}" ||
		echo "hardware-profile.sh: could not re-apply versionlock"
	echo "== versionlock entries after the swap =="
	dnf versionlock list 2>&1 || true

	# The guarantee, asserted rather than assumed.
	installed_evr="$(rpm -q "${kernel_pkg}" --qf '%{EPOCHNUM}:%{VERSION}-%{RELEASE}\n' | tail -n1)"
	if [[ "${installed_evr#0:}" != "${kernel_evr#0:}" ]]; then
		echo "ERROR: installed ${kernel_pkg} ${installed_evr} is not ${kernel_evr} from ${kernel_repo_id}" >&2
		exit 1
	fi
	echo "hardware-profile.sh: ${kernel_pkg} ${kernel_evr} is the ${kernel_repo} build"
	kernel_swapped=1
fi

kver="$(newest_kernel)"
if [[ -z "${kver}" ]]; then
	echo "ERROR: hardware profile ${PROFILE_ID} found no kernel under ${R}/usr/lib/modules" >&2
	exit 1
fi
module_dir="${R}/usr/lib/modules/${kver}"
echo "hardware-profile.sh: kernel ${kver}"

# ── 3. packages, files, conflicts ────────────────────────────────────────────
mapfile -t packages < <(values ".packages.${manager}")
if ((${#packages[@]})); then
	pkg_install "${packages[@]}"
	pkg_clean
fi
overrides="${CONTEXT}/overrides/hardware-${PROFILE_ID}"
if [[ -d "${overrides}" ]]; then
	cp -a "${overrides}/." "${R:-/}"
fi
while IFS= read -r conflict; do
	if pkg_installed "${conflict}"; then
		echo "ERROR: ${conflict} must not be present in a ${PROFILE_ID} image" >&2
		exit 1
	fi
done < <(values ".conflicts.${manager}")

# ── 4. kernel arguments ──────────────────────────────────────────────────────
mapfile -t kargs < <(values .kargs)
kargs_file="${R}/usr/lib/bootc/kargs.d/10-${PROFILE_ID}.toml"
if ((${#kargs[@]})); then
	install -d -m 0755 "${kargs_file%/*}"
	{
		echo "# Hardware profile ${PROFILE_ID}, written by build_scripts/overlay/hardware-profile.sh."
		printf 'kargs = [%s]\n' "$(printf '"%s", ' "${kargs[@]}" | sed 's/, $//')"
		printf 'match-architectures = [%s]\n' "$(values .architectures | sed 's/.*/"&"/' | paste -sd, - | sed 's/,/, /g')"
	} >"${kargs_file}"
fi

# ── 5. dracut configuration ──────────────────────────────────────────────────
# A driver goes into add_drivers only if this kernel has it as a module:
# built-in ones need no inclusion, and dracut fails on absent ones.
driver_is_module() {
	if [[ -z "${R}" ]] && command -v modinfo >/dev/null 2>&1; then
		modinfo -k "${kver}" -F filename "$1" 2>/dev/null | grep -q '\.ko'
		return
	fi
	find "${module_dir}" -regextype posix-extended -regex ".*/${1//[-_]/[-_]}\.ko(\.xz|\.zst)?" -print -quit 2>/dev/null | grep -q .
}
# The parent's own initramfs recipe: dracut-config.sh (composefs bases) leaves
# its 30-bootc-container-build.conf; ostree bases build with `--add ostree`.
dracut_dir="${R}/usr/lib/dracut/dracut.conf.d"
uses_dracut_config=0
[[ -f "${dracut_dir}/30-bootc-container-build.conf" ]] && uses_dracut_config=1
mapfile -t kms_drivers < <(values .initramfs.kms_drivers)
mapfile -t wanted_drivers < <(values .initramfs.add_drivers)
# Without dracut-config.sh nothing else adds the profile's display drivers.
((uses_dracut_config)) || wanted_drivers+=("${kms_drivers[@]}")
loadable=()
for module in "${wanted_drivers[@]}"; do
	if driver_is_module "${module}" && [[ " ${loadable[*]} " != *" ${module} "* ]]; then
		loadable+=("${module}")
	fi
done
mapfile -t omit_drivers < <(values .initramfs.omit_drivers)
mapfile -t dracut_modules < <(values .initramfs.dracut_modules)
rebuild_initramfs=0
if ((${#wanted_drivers[@]} + ${#omit_drivers[@]} + ${#dracut_modules[@]} + ${#kms_drivers[@]})); then
	rebuild_initramfs=1
	install -d -m 0755 "${dracut_dir}"
	{
		echo "# Hardware profile ${PROFILE_ID}, written by build_scripts/overlay/hardware-profile.sh."
		((${#loadable[@]})) && echo "add_drivers+=\" ${loadable[*]} \""
		((${#dracut_modules[@]})) && echo "add_dracutmodules+=\" ${dracut_modules[*]} \""
		((${#omit_drivers[@]})) && echo "omit_drivers+=\" ${omit_drivers[*]} \""
		true
	} >"${dracut_dir}/90-${PROFILE_ID}.conf"
	printf 'hardware-profile.sh: %d of %d early-boot drivers are loadable modules; the rest are built in or absent\n' \
		"${#loadable[@]}" "${#wanted_drivers[@]}"
fi

# ── 6. device tree ───────────────────────────────────────────────────────────
# composefs images boot through systemd-boot; ostree images through GRUB.
layout=ostree
if grep -A8 '^\[composefs\]' "${R}/usr/lib/ostree/prepare-root.conf" 2>/dev/null |
	grep -qiE 'enabled[[:space:]]*=[[:space:]]*(yes|true|1|signed)'; then
	layout=composefs
fi
dtb_rel="$(values .devicetree.dtb)"
dtb=""
stub_sections=""
if [[ -n "${dtb_rel}" ]]; then
	# Every base keeps its kernel's DTBs here; bootc/ostree-layout.sh moves
	# Arch's /boot/dtbs into it before wiping /boot.
	dtb="${module_dir}/dtb/${dtb_rel}"
	if [[ ! -s "${dtb}" ]]; then
		echo "ERROR: kernel ${kver} has no device tree ${dtb_rel}" >&2
		exit 1
	fi
	if [[ "${layout}" == ostree ]]; then
		# ostree deploys /usr/lib/modules/$kver/devicetree into each
		# deployment's /boot and writes a `devicetree` line into its boot
		# entry, which GRUB (blscfg) and systemd-boot both load, so every
		# deployment and rollback boots the DTB built with its own kernel.
		# With only the dtb/ directory, ostree writes `fdtdir`, which GRUB
		# ignores.
		install -m 0644 "${dtb}" "${module_dir}/devicetree"
	else
		# bootc's composefs systemd-boot entries carry no `devicetree` line
		# (tuna-os/bootc-migrate#461). Instead the kernel itself carries the
		# DTB: wrap vmlinuz in systemd-stub with a .dtbauto section and the
		# hardware-ID table, so the stub picks this DTB by the machine's CHID.
		# The initramfs and command line still come from the boot entry; the
		# stub adds no .cmdline. This is the mechanism of Fedora's
		# kernel-dtb-loader.
		case "${arch}" in
		aarch64) efi_arch=aa64 ;;
		x86_64) efi_arch=x64 ;;
		esac
		ukify_installed=0
		if ! command -v ukify >/dev/null 2>&1; then
			if [[ "${manager}" == pacman ]]; then
				# systemd-ukify pins systemd to its own version; installing it
				# against a different systemd would be a partial upgrade of the
				# init system. The dependency names a pkgver (systemd=262.1);
				# pacman -Q adds -pkgrel.
				ukify_systemd="$(pacman -Si systemd-ukify | sed -n 's/^Depends On *: .*systemd=\([^ ]*\).*/\1/p')"
				installed_systemd="$(pacman -Q systemd | awk '{print $2}')"
				if [[ "${installed_systemd%-*}" != "${ukify_systemd%-*}" ]]; then
					echo "ERROR: systemd-ukify needs systemd ${ukify_systemd}; the parent has ${installed_systemd}; rebuild the parent first" >&2
					exit 1
				fi
			fi
			pkg_install systemd-ukify
			ukify_installed=1
		fi
		stub_image="$(mktemp)"
		ukify build \
			--linux="${module_dir}/vmlinuz" \
			--devicetree-auto="${dtb}" \
			--hwids="/usr/lib/systemd/boot/hwids/${efi_arch}" \
			--stub="/usr/lib/systemd/boot/efi/linux${efi_arch}.efi.stub" \
			--uname="${kver}" \
			--output="${stub_image}"
		# Record the PE sections while pefile (a ukify dependency) is installed.
		stub_sections="$(python3 -c 'import pefile, sys
for s in pefile.PE(sys.argv[1], fast_load=True).sections:
    print(s.Name.rstrip(b"\0").decode())' "${stub_image}")"
		install -m 0755 "${stub_image}" "${module_dir}/vmlinuz"
		rm -f "${stub_image}"
		if ((ukify_installed)); then
			case "${manager}" in
			pacman) pacman -Rns --noconfirm systemd-ukify ;;
			dnf) dnf -y remove systemd-ukify ;;
			*) : ;;
			esac
			pkg_clean
		fi
	fi
fi

# ── 7. initramfs ─────────────────────────────────────────────────────────────
if ((rebuild_initramfs)); then
	if ((uses_dracut_config)); then
		# As Containerfile.arch does: dracut-config.sh writes the bootc
		# configuration with the profile's GPU as the early-KMS list, then
		# dracut builds against the named kernel.
		TUNAOS_DRACUT_KMS_DRIVERS="${kms_drivers[*]}" "${CONTEXT}/build_scripts/bootc/dracut-config.sh" "${kver}"
		dracut --force "${module_dir}/initramfs.img" "${kver}"
	else
		# As 26-packages-post.sh does for ostree bases.
		mkdir -p "${R}/var/roothome"
		chmod 0700 "${R}/var/roothome"
		DRACUT_NO_XATTR=1 dracut --tmpdir /tmp --no-hostonly --kver "${kver}" --reproducible --zstd --add ostree \
			-f "${module_dir}/initramfs.img"
	fi
elif ((kernel_swapped)); then
	echo "hardware-profile.sh: initramfs already rebuilt for the swapped kernel"
fi

# ── 8. inventory ─────────────────────────────────────────────────────────────
mapfile -t require_kconfig < <(values .require.kconfig)
mapfile -t optional_kconfig < <(values .require.kconfig_optional)
mapfile -t require_modules < <(values .require.modules)
mapfile -t require_firmware < <(values .require.firmware)
config=""
for candidate in "${module_dir}/config" "${R}/boot/config-${kver}" "${module_dir}/build/.config"; do
	if [[ -r "${candidate}" ]]; then
		config="${candidate}"
		break
	fi
done

report_dir="${R}/usr/share/tunaos"
report="${report_dir}/hardware-${PROFILE_ID}.txt"
tmp_report="$(mktemp)"
trap 'rm -f "${tmp_report}"' EXIT
{
	echo "Hardware profile ${PROFILE_ID} inspection (${manager}, ${layout})"
	echo "architecture=${arch}"
	echo "kernel=${kver}"
	echo "base_image=${BASE_IMAGE:-unknown}"
	if ((${#require_kconfig[@]} + ${#optional_kconfig[@]})); then
		echo
		echo "[kernel-config]"
		if [[ -z "${config}" ]]; then
			echo "MISSING kernel configuration for ${kver}"
		else
			for symbol in "${require_kconfig[@]}"; do inventory_kconfig "${config}" "${symbol}"; done
			for symbol in "${optional_kconfig[@]}"; do inventory_kconfig "${config}" "${symbol}" optional; done
		fi
	fi
	if ((${#require_modules[@]})); then
		echo
		echo "[modules]"
		for module in "${require_modules[@]}"; do inventory_module "${module_dir}" "${module}"; done
	fi
	echo
	echo "[boot]"
	if [[ -n "${dtb}" && "${layout}" == ostree ]]; then
		if cmp -s "${dtb}" "${module_dir}/devicetree"; then
			echo "PRESENT devicetree -> ${module_dir}/devicetree (${dtb_rel})"
		else
			echo "MISSING devicetree ${module_dir}/devicetree"
		fi
	elif [[ -n "${dtb}" ]]; then
		for section in linux dtbauto hwids; do
			if grep -q "^\.${section}" <<<"${stub_sections}"; then
				echo "PRESENT vmlinuz section .${section}"
			else
				echo "MISSING vmlinuz section .${section}"
			fi
		done
	fi
	if ((${#kargs[@]})); then
		grep -h '^kargs' "${kargs_file}" 2>/dev/null || echo "MISSING kargs ${kargs_file}"
	fi
	if ((rebuild_initramfs)); then
		echo
		echo "[initramfs]"
		initramfs_list="$(lsinitrd "${module_dir}/initramfs.img")"
		# lsinitrd lists the dracut modules between "dracut modules:" and the
		# next rule line, then the files.
		included_modules="$(sed -n '/^dracut modules:/,/^=\{10,\}/p' <<<"${initramfs_list}")"
		for module in "${loadable[@]}"; do
			if grep -qE "/${module//[-_]/[-_]}\.ko" <<<"${initramfs_list}"; then
				echo "PRESENT ${module}"
			else
				echo "MISSING ${module} (initramfs)"
			fi
		done
		for module in "${dracut_modules[@]}"; do
			if grep -qx "${module}" <<<"${included_modules}"; then
				echo "PRESENT dracut module ${module}"
			else
				echo "MISSING dracut module ${module} (initramfs)"
			fi
		done
	fi
	if ((${#require_firmware[@]})); then
		echo
		echo "[firmware]"
		for firmware in "${require_firmware[@]}"; do inventory_file "${R}${firmware}"; done
	fi
} | tee "${tmp_report}"

install -d -m 0755 "${report_dir}"
install -m 0644 "${tmp_report}" "${report}"
echo "hardware-profile.sh: inspection stored at ${report}"
printf '::endgroup::\n'

# A missing symbol, module, DTB, argument, early driver or firmware file fails
# the build instead of shipping a blind or dark machine.
if grep -q '^MISSING ' "${report}"; then
	echo "ERROR: hardware profile ${PROFILE_ID} payload incomplete:" >&2
	grep '^MISSING ' "${report}" >&2
	exit 1
fi
